/**
 * @file hazard_sweep_subset_test.cpp
 * @brief The strongest cases of E6's hazard sweep, kept in the suite: every
 *        consumer mnemonic x source slot right behind a load of that register,
 *        on the two models that own hazards (rv5-h-nf, rv5-h-f).
 *
 * The full sweep (~/atlas-verify/e6/hazgen.py, out of tree) runs every
 * producer class at distances 0-3 on all five models, unpadded. This subset
 * is distance 0 with a load producer (ld for an integer slot, fld for an FP
 * slot), plus the FP-store cases E6 fixed: fsw/fsd with imm[4:0] = 5, then a
 * reader of f5. Before that fix an FP store claimed to write f[imm[4:0]], so
 * h_nf stalled for nothing and h_f forwarded the store's ADDRESS as f5.
 *
 * Each case checks, against values computed without the simulator
 * (~/atlas-verify/e6/gen_subset.py):
 *   - the consumer's result (E3's RV64IM alu(), E5's fpo.py, spec code for
 *     loads, stores, branches, jalr and the CSR forms);
 *   - the cycle count, from the pipeline rules: ID-time recurrence, h_nf waits
 *     until its producer's WB, h_f only for a load's reader (1 bubble),
 *     +2 per jump, +3 per taken branch, +4 per CSR instruction (served at WB;
 *     a redirect's target is fetched the next cycle, rv5s_processor_base.cpp:493);
 *   - every x and f register equal to rvss's on the same program.
 */
#include "isa_case_support.h"

#include <gtest/gtest.h>

#include <string>
#include <utility>
#include <vector>

using namespace Atlas;
using namespace Atlas::test_support;

